                ['x' => 50, 'y' => 20, 'label_en' => 'The window above', 'label_ku' => 'پەنجەرەی سەرەوە', 'label_ar' => 'النافذة في الأعلى', 'text_en' => 'A grilled window in a carved frame lit the rooms over the passage. The harem had two storeys, and clues in the masonry suggest a smaller third; the upper floors are gone.', 'text_ku' => 'پەنجەرەیەکی تۆڕدار لە چوارچێوەیەکی هەڵکەنراودا ژوورەکانی سەرووی ڕێڕەوەکەی ڕووناک دەکردەوە. حەرەمەکە دوو نهۆمی هەبوو، و نیشانەکانی بەردکاری ئاماژە بە سێیەمێکی بچووکتر دەکەن؛ نهۆمە سەرەوەکان نەماون.', 'text_ar' => 'نافذة مشبّكة في إطار منحوت أضاءت الغرف فوق الممر. كان للحرم طابقان، وتشير دلائل في البناء إلى ثالث أصغر؛ وقد زالت الطوابق العليا.'],
                ['x' => 8, 'y' => 80, 'label_en' => 'A small animal', 'label_ku' => 'ئاژەڵێکی بچووک', 'label_ar' => 'حيوان صغير', 'text_en' => 'At the foot of the left jamb a four-legged creature stands in the stone — one of many birds and beasts in the reliefs. Figures were unusual in Ottoman religious art but at home in this borderland.', 'text_ku' => 'لە بنی لاتەنیشتی چەپدا گیانلەبەرێکی چوارپێ لە بەردەکەدا ڕاوەستاوە — یەکێک لە زۆر باڵندە و ئاژەڵی نەخشەکان. پەیکەر لە هونەری ئایینیی عوسمانیدا نائاسایی بوو بەڵام لەم سنوورەدا ئاسایی بوو.', 'text_ar' => 'عند أسفل القائمة اليسرى يقف في الحجر مخلوق ذو أربع قوائم — واحد من طيور ووحوش كثيرة في النقوش. كانت الهيئات نادرة في الفن الديني العثماني لكنها مألوفة في هذا الثغر.'],
                ['x' => 52, 'y' => 76, 'label_en' => 'The door itself', 'label_ku' => 'دەرگاکە خۆی', 'label_ar' => 'الباب نفسه', 'text_en' => 'A second, smaller frame holds the opening, which leads into a long straight corridor to the harem. The gilded wooden doors that once hung here were taken to Russia in 1828 and are reported to be in the Hermitage.', 'text_ku' => 'چوارچێوەیەکی دووەمی بچووکتر کونەکە دەگرێت، کە بەرەو ڕێڕەوێکی درێژی ڕاست بۆ حەرەم دەچێت. دەرگا دارینە زێڕکراوەکان کە جارێک لێرە هەڵواسرابوون لە ١٨٢٨ بردرانە ڕووسیا و ڕاپۆرت دەکرێت لە هێرمیتاژدان.', 'text_ar' => 'إطار ثانٍ أصغر يحمل الفتحة المفضية إلى ممر طويل مستقيم نحو الحرم. أما الأبواب الخشبية المذهّبة التي كانت معلّقة هنا فنُقلت إلى روسيا عام ١٨٢٨ ويُقال إنها في الإرميتاج.'],
            ],
        ]],

