                ['date_en' => '1828', 'date_ku' => '1828', 'date_ar' => '1828', 'title_en' => 'Russian occupation', 'title_ku' => 'داگیرکاریی ڕووسی', 'title_ar' => 'الاحتلال الروسي', 'text_en' => 'A year long. The gilded doors and the library go to Russia; much woodwork is burned.', 'text_ku' => 'ساڵێک درێژ. دەرگا زێڕکراوەکان و کتێبخانەکە بۆ ڕووسیا دەچن؛ زۆر دارکاری دەسووتێت.', 'text_ar' => 'دام عاماً. تذهب الأبواب المذهّبة والمكتبة إلى روسيا؛ ويُحرق كثير من الخشب.'],
                ['date_en' => '1830', 'date_ku' => '1830', 'date_ar' => '1830', 'title_en' => 'Charles Texier describes the palace', 'title_ku' => 'شارل تێکسیە کۆشکەکە وەسف دەکات', 'title_ar' => 'شارل تكسييه يصف القصر', 'text_en' => 'The first European account, with the painted ceilings still in place.', 'text_ku' => 'یەکەم گێڕانەوەی ئەورووپی، بە سەقفە ڕەنگکراوەکان هێشتا لە جێی خۆیاندا.', 'text_ar' => 'أول رواية أوروبية، والسقوف المرسومة ما تزال في مكانها.'],
